import { editTieFormat } from 'components/overlays/editTieFormat.js/editTieFormat';
import type { RoundProfileEditorController } from './roundProfileEditor';
import { mutationRequest } from 'services/mutation/mutationRequest';
import { tmxToast } from 'services/notifications/tmxToast';
import { tournamentEngine } from 'services/factory/engine';
import { validators } from 'courthive-components';
import { resolveSeedsCount } from './seedCount';
import { generateDraw } from './generateDraw';
import { isFunction } from 'functions/typeOf';
import { t } from 'i18n';

// constants
import { ADD_DRAW_ENTRIES, ATTACH_QUALIFYING_STRUCTURE, SET_POSITION_ASSIGNMENTS } from 'constants/mutationConstants';
import {
  AUTOMATED,
  BEST_FINISHERS,
  CUSTOM,
  DRAFT,
  DRAW_MATIC,
  DRAW_NAME,
  DRAW_SIZE,
  DRAW_TYPE,
  DYNAMIC_RATINGS,
  FIC_DEPTH,
  GROUP_REMAINING,
  GROUP_SIZE,
  MATCHUP_FORMAT,
  PLAYOFF_DRAW_TYPE,
  PLAYOFF_GROUP_SIZE,
  PLAYOFF_TYPE,
  POSITIONS,
  QUALIFIERS_COUNT,
  QUALIFYING_FIRST,
  QUALIFYING_POSITIONS,
  QUALIFYING_TARGET_ROUND,
  RATING_SCALE,
  ROUNDS_COUNT,
  SEEDING_POLICY,
  SEEDS_COUNT,
  STRUCTURE_NAME,
  TEAM_AVOIDANCE,
  TOP_FINISHERS,
  TOTAL_ADVANCE,
} from 'constants/tmxConstants';

const {
  AD_HOC,
  ADAPTIVE,
  FEED_IN,
  LUCKY_DRAW,
  MAIN,
  PAGE_PLAYOFF,
  QUALIFYING,
  FEED_IN_CHAMPIONSHIP,
  FEED_IN_CHAMPIONSHIP_TO_QF,
  FEED_IN_CHAMPIONSHIP_TO_R16,
  FEED_IN_CHAMPIONSHIP_TO_SF,
  ROUND_ROBIN,
  ROUND_ROBIN_WITH_PLAYOFF,
  SWISS,
} = drawDefinitionConstants;
const { DIRECT_ENTRY_STATUSES } = entryStatusConstants;

const IS_WARNING = 'is-warning';

/**
 * Apply draw-type-specific options into the in-progress drawOptions object.
 * Currently handles the AD_HOC (with optional DrawMatic configuration) and
 * SWISS branches; other draw types pass through unchanged.
 */
function applyDrawTypeOptions({
  drawOptions,
  drawType,
  isDrawMatic,
  inputs,
}: {
  drawOptions: any;
  drawType: string;
  isDrawMatic: boolean;
  inputs: any;
}): void {
  if (drawType === AD_HOC) {
    if (isDrawMatic) {
      const roundsCount = Number.parseInt(inputs[ROUNDS_COUNT]?.value) || 1;
      const selectedScale = inputs[RATING_SCALE]?.value || '';
      const dynamicRatings = inputs[DYNAMIC_RATINGS]?.checked || false;
      const teamAvoidance = inputs[TEAM_AVOIDANCE]?.checked || false;
      Object.assign(drawOptions, {
        automated: true,
        roundsCount,
        drawMatic: {
          dynamicRatings,
          convertToELO: dynamicRatings,
          ...(selectedScale && { scaleName: selectedScale.toUpperCase() }),
          ...(teamAvoidance === false && { sameTeamValue: 0 }),
        },
      });
    } else {
      Object.assign(drawOptions, { roundsCount: 1 });
    }
    return;
  }

  if (drawType === SWISS) {
    const selectedScale = inputs[RATING_SCALE]?.value || '';
    Object.assign(drawOptions, {
      automated: false,
      ...(selectedScale && { scaleName: selectedScale.toUpperCase() }),
    });
  }
}

/**
 * Wrap a draw-creation callback so that, after a qualifying-first draw is
 * generated, the qualifying-stage entries are auto-positioned in the new
 * qualifying structure before the original callback fires.
 *
 * Returns the original callback unchanged when qualifying-first auto-positioning
 * doesn't apply (no auto-positioning or no qualifying-first flag).
 */
function buildQualifyingFirstCallback(
  isQualifyingFirst: boolean,
  automated: any,
  callback?: (result: any) => void,
): ((result: any) => void) | undefined {
  if (!isQualifyingFirst || !automated) return callback;

  return (result: any) => {
    const qualifyingStructureId = result.drawDefinition?.structures?.find(
      (s: any) => s.stage === QUALIFYING,
    )?.structureId;
    const generatedDrawId = result.drawDefinition?.drawId;

    if (qualifyingStructureId && generatedDrawId) {
      const positionResult = tournamentEngine.automatedPositioning({
        structureId: qualifyingStructureId,
        applyPositioning: false,
        drawId: generatedDrawId,
      });
      if (positionResult.success && positionResult.positionAssignments?.length) {
        mutationRequest({
          methods: [
            {
              method: SET_POSITION_ASSIGNMENTS,
              params: {
                structurePositionAssignments: [
                  { structureId: qualifyingStructureId, positionAssignments: positionResult.positionAssignments },
                ],
                structureId: qualifyingStructureId,
                drawId: generatedDrawId,
              },
            },
          ],
          callback: () => {
            if (isFunction(callback)) callback(result);
          },
        });
        return;
      }
    }
    if (isFunction(callback)) callback(result);
  };
}

function getPlayoffGroups(
  playoffType: string,
  advancePerGroup: number,
  groupRemaining: boolean,
  groupSize: number,
  inputs?: any,
): any[] {
  const playoffGroups: any[] = [];

  // Get the selected playoff draw type and optional playoff group size
  const playoffDrawType = inputs?.[PLAYOFF_DRAW_TYPE]?.value;
  const playoffGroupSize = inputs?.[PLAYOFF_GROUP_SIZE]?.value
    ? Number.parseInt(inputs[PLAYOFF_GROUP_SIZE].value)
    : undefined;

  // Build extra properties to spread into each playoff group
  const playoffDrawProps: any = {};
  if (playoffDrawType) {
    playoffDrawProps.drawType = playoffDrawType;
  }
  if (playoffDrawType === ROUND_ROBIN && playoffGroupSize) {
    playoffDrawProps.structureOptions = { groupSize: playoffGroupSize };
  }

  if (playoffType === TOP_FINISHERS) {
    const groups = [tools.generateRange(1, advancePerGroup + 1)];
    if (groupRemaining) {
      const group = tools.generateRange(advancePerGroup + 1, groupSize + 1);
      if (group.length) groups.push(group);
    }
    groups.forEach((finishingPositions, i) => {
      playoffGroups.push({
        structureName: `Playoff ${i + 1}`,
        finishingPositions,
        ...playoffDrawProps,
      });
    });
  } else if (playoffType === BEST_FINISHERS) {
    const totalAdvance = Number.parseInt(inputs[TOTAL_ADVANCE]?.value || 0);
    if (totalAdvance > 0) {
      playoffGroups.push({
        finishingPositions: [1],
        bestOf: totalAdvance,
        rankBy: 'GEMscore',
        structureName: 'Playoff 1',
        ...playoffDrawProps,
      });
      if (groupRemaining) {
        playoffGroups.push({
          remainder: true,
          structureName: 'Playoff 2',
          ...playoffDrawProps,
        });
      }
    }
  } else if (playoffType === POSITIONS) {
    tools.generateRange(1, groupSize + 1).forEach((c) => {
      playoffGroups.push({
        structureName: `Playoff ${c}`,
        finishingPositions: [c],
        ...playoffDrawProps,
      });
    });
  }

  return playoffGroups;
}

function validatePagePlayoff(structureOptions: any, inputs: any, groupSize: number): boolean | undefined {
  const pagePlayoffGroup = structureOptions?.playoffGroups?.find((pg: any) => pg.drawType === PAGE_PLAYOFF);
  if (!pagePlayoffGroup) return undefined;

  const drawSizeValue = Number.parseInt(inputs[DRAW_SIZE]?.value || '0');
  const groupCount = Math.floor(drawSizeValue / groupSize);
  const finishingPositions = pagePlayoffGroup.finishingPositions || [];
  const expectedCount = pagePlayoffGroup.bestOf || groupCount * finishingPositions.length;

  if (expectedCount !== 4) {
    tmxToast({
      message: `Page Playoff requires exactly 4 finishers (current configuration produces ${expectedCount})`,
      intent: IS_WARNING,
      pauseOnHover: true,
    });
    return false;
  }
  return true;
}

function getStructureOptions(drawType: string, inputs: any): any {
  const groupSize = Number.parseInt(inputs[GROUP_SIZE].value);

  if (drawType === ROUND_ROBIN_WITH_PLAYOFF) {
    const advancePerGroup = Number.parseInt(inputs.advancePerGroup?.value || 0);
    const groupRemaining = inputs[GROUP_REMAINING]?.checked;
    const playoffType = inputs[PLAYOFF_TYPE]?.value;
    const playoffGroups = getPlayoffGroups(playoffType, advancePerGroup, groupRemaining, groupSize, inputs);

    const structureOptions: any = { groupSize };
    if (playoffGroups.length) {
      structureOptions.playoffGroups = playoffGroups;
    } else {
      // WINNERS case: group winners advance; pass drawType if non-default
      const playoffDrawType = inputs?.[PLAYOFF_DRAW_TYPE]?.value;
      const playoffGroupSize = inputs?.[PLAYOFF_GROUP_SIZE]?.value
        ? Number.parseInt(inputs[PLAYOFF_GROUP_SIZE].value)
        : undefined;
      if (playoffDrawType) {
        structureOptions.playoffGroups = [
          {
            finishingPositions: [1],
            drawType: playoffDrawType,
            ...(playoffDrawType === ROUND_ROBIN && playoffGroupSize
              ? { structureOptions: { groupSize: playoffGroupSize } }
              : {}),
          },
        ];
      }
    }

    // Validate PAGE_PLAYOFF requires exactly 4 participants in the playoff
    if (validatePagePlayoff(structureOptions, inputs, groupSize) === false) return undefined;

    return structureOptions;
  } else if (drawType === ROUND_ROBIN) {
    return { groupSize };
  }

  return undefined;
}

function handleQualifyingStructure(params: {
  structureId: string;
  qualifiersCount: number;
  roundTarget?: number;
  structureOptions: any;
  matchUpFormat: string;
  structureName: string;
  automated: any;
  drawSize: number;
  drawType: string;
  drawId: string;
  eventId: string;
  callback?: (result: any) => void;
}): void {
  const {
    structureId,
    qualifiersCount,
    structureOptions,
    matchUpFormat,
    structureName,
    roundTarget,
    automated,
    drawSize,
    drawType,
    drawId,
    eventId,
    callback,
  } = params;

  const generationResult = tournamentEngine.generateQualifyingStructure({
    qualifyingPositions: qualifiersCount,
    targetStructureId: structureId,
    structureOptions,
    matchUpFormat,
    structureName,
    roundTarget,
    drawSize,
    drawType: drawType as any,
    drawId,
  });

  if (generationResult.success) {
    const qualifyingStructureId = generationResult.structure?.structureId;
    const methods: any[] = [
      {
        method: ATTACH_QUALIFYING_STRUCTURE,
        params: {
          structure: generationResult.structure,
          link: generationResult.link,
          eventId,
          drawId,
        },
      },
    ];

    // Add qualifying entries to the draw so automatedPositioning can find them
    const event = tournamentEngine.q.event({ eventId });
    const qualifyingParticipantIds = (event?.entries ?? [])
      .filter((e: any) => e.entryStage === QUALIFYING && DIRECT_ENTRY_STATUSES.includes(e.entryStatus))
      .map((e: any) => e.participantId);
    if (qualifyingParticipantIds.length) {
      methods.push({
        method: ADD_DRAW_ENTRIES,
        params: {
          participantIds: qualifyingParticipantIds,
          entryStage: QUALIFYING,
          ignoreStageSpace: true,
          eventId,
          drawId,
        },
      });
    }

    const postMutation = (result: any) => {
      // the factory refuses a qualifying that would overfill its round (QUALIFYING_CAPACITY_EXCEEDED)
      const failure = result?.error ?? result?.results?.find((r: any) => r?.error)?.error;
      if (failure) tmxToast({ message: failure.message ?? t('common.error'), intent: 'is-danger' });
      if (result.success && automated && qualifyingStructureId) {
        const positionResult = tournamentEngine.automatedPositioning({
          structureId: qualifyingStructureId,
          applyPositioning: false,
          drawId,
        });
        if (positionResult.success && positionResult.positionAssignments?.length) {
          mutationRequest({
            methods: [
              {
                method: SET_POSITION_ASSIGNMENTS,
                params: {
                  structurePositionAssignments: [
                    { structureId: qualifyingStructureId, positionAssignments: positionResult.positionAssignments },
                  ],
                  structureId: qualifyingStructureId,
                  drawId,
                },
              },
            ],
            callback: (positionMutationResult: any) => {
              if (isFunction(callback)) callback({ ...generationResult, ...positionMutationResult.results?.[0] });
            },
          });
          return;
        }
      }
      if (isFunction(callback)) callback({ ...generationResult, ...result.results?.[0] });
    };
    mutationRequest({ methods, callback: postMutation });
  } else {
    tmxToast({ message: generationResult.error?.message ?? t('common.error'), intent: 'is-danger' });
    if (isFunction(callback)) callback(generationResult);
  }
}

function configureDrawOptions(params: {
  isQualifying: boolean;
  existingDrawName?: string;
  qualifiersCount: number;
  structureOptions: any;
  matchUpFormat: string;
  structureName: string;
  seedsCount: number;
  drawSize: number;
  drawType: string;
  drawName: string;
  eventId: string;
  drawOptions: any;
}): void {
  const {
    isQualifying,
    existingDrawName,
    qualifiersCount,
    structureOptions,
    matchUpFormat,
    structureName,
    seedsCount,
    drawSize,
    drawType,
    drawName,
    eventId,
    drawOptions,
  } = params;

  if (isQualifying) {
    drawOptions.drawName = existingDrawName || drawName;
    drawOptions.qualifyingProfiles = [
      {
        structureProfiles: [
          {
            qualifyingPositions: qualifiersCount,
            structureOptions,
            matchUpFormat,
            structureName,
            seedsCount,
            drawSize,
            drawType,
          },
        ],
      },
    ];
  } else {
    if (qualifiersCount) {
      drawOptions.qualifiersCount = qualifiersCount;
      drawOptions.qualifyingPlaceholder = true;
    }
    Object.assign(drawOptions, {
      seedingScaleName: eventId,
      structureOptions,
      matchUpFormat,
      seedsCount,
      drawName,
      drawSize,
      drawType,
    });
  }
}

function handleDrawGeneration(params: {
  drawOptions: any;
  tieFormatName: string;
  seedingPolicyDefinition: any;
  eventId: string;
  callback?: (result: any) => void;
}): void {
  const { drawOptions, tieFormatName, seedingPolicyDefinition, eventId, callback } = params;

  if (tieFormatName === CUSTOM) {
    const setTieFormat = (tieFormat: any) => {
      if (tieFormat) {
        drawOptions.tieFormat = tieFormat;
        generateDraw({ drawOptions, eventId, callback });
      }
    };
    editTieFormat({ title: t('drawers.addDraw.customScorecard'), tieFormat: undefined, onClose: setTieFormat });
  } else {
    drawOptions.tieFormatName = tieFormatName;

    if (seedingPolicyDefinition) {
      drawOptions.policyDefinitions = {
        ...drawOptions.policyDefinitions,
        ...seedingPolicyDefinition,
      };
    }

    generateDraw({ drawOptions, eventId, callback });
  }
}

/** Resolve which entries become the new draw's `drawEntries`.
 *  Priority:
 *   1. Caller's explicit `selectedParticipantIds` (from a unified-table selection).
 *   2. Qualifying-stage event entries when the form is in a qualifying flow.
 *   3. The flight's MAIN drawEntries, if any.
 *   4. Event-level MAIN entries as the final fallback. */
function resolveDrawEntries({
  event,
  flight,
  effectiveIsQualifying,
  qualifyingEntries,
  selectedParticipantIds,
}: {
  event: any;
  flight: any;
  effectiveIsQualifying: boolean;
  qualifyingEntries: any[];
  selectedParticipantIds?: string[];
}): any[] {
  if (selectedParticipantIds?.length) {
    const selectedSet = new Set<string>(selectedParticipantIds);
    const selectionEntries = event.entries.filter((e: any) => selectedSet.has(e.participantId));
    if (selectionEntries.length) return selectionEntries;
  }
  if (effectiveIsQualifying && qualifyingEntries.length) return qualifyingEntries;
  const flightMainEntries = (flight?.drawEntries || []).filter(
    ({ entryStage, entryStatus }: any) =>
      (!entryStage || entryStage === MAIN) && DIRECT_ENTRY_STATUSES.includes(entryStatus),
  );
  if (flightMainEntries.length) return flightMainEntries;
  return event.entries.filter(
    ({ entryStage, entryStatus }: any) =>
      (!entryStage || entryStage === MAIN) && DIRECT_ENTRY_STATUSES.includes(entryStatus),
  );
}

export function submitDrawParams({
  drawName: existingDrawName,
  matchUpFormat: providedMatchUpFormat,
  isPopulateMain,
  isQualifying,
  structureId,
  callback,
  inputs,
  drawId,
  event,
  roundProfileEditor,
  selectedParticipantIds,
}: {
  drawName?: string;
  matchUpFormat?: string;
  isPopulateMain?: boolean;
  isQualifying?: boolean;
  structureId?: string;
  callback?: (result: any) => void;
  inputs: any;
  drawId?: string;
  event: any;
  roundProfileEditor?: RoundProfileEditorController;
  selectedParticipantIds?: string[];
}): void {
  const isQualifyingFirst = inputs[QUALIFYING_FIRST]?.checked && !drawId && !structureId;
  const rawDrawType = inputs[DRAW_TYPE].options[inputs[DRAW_TYPE].selectedIndex].getAttribute('value');
  const isDrawMatic = rawDrawType === DRAW_MATIC;

  const FIC_DEPTH_MAP: Record<string, string> = {
    F: FEED_IN_CHAMPIONSHIP,
    SF: FEED_IN_CHAMPIONSHIP_TO_SF,
    QF: FEED_IN_CHAMPIONSHIP_TO_QF,
    R16: FEED_IN_CHAMPIONSHIP_TO_R16,
  };
  const resolvedFIC =
    rawDrawType === FEED_IN_CHAMPIONSHIP ? FIC_DEPTH_MAP[inputs[FIC_DEPTH]?.value] || FEED_IN_CHAMPIONSHIP : undefined;

  const drawType = resolvedFIC || (isDrawMatic ? AD_HOC : rawDrawType);
  const matchUpFormat = providedMatchUpFormat || inputs[MATCHUP_FORMAT]?.value;
  const selectedSeedingPolicy = inputs[SEEDING_POLICY]?.value;

  const flightProfile = tournamentEngine.q.flightProfile({ event });
  const flight = flightProfile?.flights?.find((f: any) => f.drawId === drawId);

  const structureName = inputs[STRUCTURE_NAME]?.value;
  const tieFormatName = inputs.tieFormatName?.value;
  const drawName = inputs[DRAW_NAME]?.value;

  const drawSizeValue = inputs[DRAW_SIZE].value || 0;
  const drawSizeInteger = tools.isConvertableInteger(drawSizeValue) && Number.parseInt(drawSizeValue);
  const effectiveIsQualifying = isQualifying || isQualifyingFirst;
  const drawSize =
    ([ADAPTIVE, LUCKY_DRAW, FEED_IN, ROUND_ROBIN, ROUND_ROBIN_WITH_PLAYOFF, AD_HOC, SWISS].includes(drawType) &&
      drawSizeInteger) ||
    (effectiveIsQualifying && drawSizeInteger) ||
    tools.nextPowerOf2(drawSizeInteger);
  const qualifyingEntries = event.entries.filter(
    ({ entryStage, entryStatus }: any) => entryStage === QUALIFYING && DIRECT_ENTRY_STATUSES.includes(entryStatus),
  );
  const drawEntries = resolveDrawEntries({
    event,
    flight,
    effectiveIsQualifying,
    qualifyingEntries,
    selectedParticipantIds,
  });

  // Only entries that will actually contend for the new draw's stage count
  // against drawSize. Cross-stage entries ride along on drawDefinition.entries
  // (see generateNewDrawDefinition.addEntries) and don't occupy structure
  // positions, so they must not feed `automated`, `requiredPositions`, or
  // the validation toast below.
  const stageEntries = drawEntries.filter((e: any) =>
    effectiveIsQualifying ? e.entryStage === QUALIFYING : !e.entryStage || e.entryStage === MAIN,
  );

  const creationValue = inputs[AUTOMATED].value;
  const isDraft = creationValue === DRAFT;
  const isLucky = drawType === LUCKY_DRAW;
  const automated =
    drawSize < stageEntries.length ? false : isDraft ? { seedsOnly: true } : isLucky || creationValue === AUTOMATED;

  const eventId = event.eventId;
  const drawOptions: any = {
    drawEntries,
    automated,
    eventId,
    drawId,
    isDraft,
  };

  // LUCKY_DRAW: thread the explicit per-round matchUp-count profile from the
  // editor into the factory when valid. If the editor returns null (e.g., odd
  // drawSize, where the editor is disabled), omit the param and let the factory
  // fall back to its default ceil-halving cascade.
  if (drawType === LUCKY_DRAW) {
    const roundProfile = roundProfileEditor?.getProfile();
    if (roundProfile) drawOptions.roundProfile = roundProfile;
  }

  const structureOptions = getStructureOptions(drawType, inputs);
  if (structureOptions === undefined && drawType === ROUND_ROBIN_WITH_PLAYOFF) return;

  applyDrawTypeOptions({ drawOptions, drawType, isDrawMatic, inputs });

  const seedingPolicyDefinition = getSeedingPolicyDefinition(selectedSeedingPolicy);

  // `getSeedingAllowance` passes the operator's drawSize for the same reason the option list does:
  // without it getSeedsCount derives one from participantsCount, so the number resolved here would
  // answer a slightly different question than the one the factory asks when it clamps during
  // generation. It is the same call the `<select>` was built from, so the count submitted and the
  // count offered cannot disagree.
  const { thresholdSeedsCount, additionalSeedsAllowed } = getSeedingAllowance({
    selectedSeedingPolicy: selectedSeedingPolicy || INHERIT,
    participantsCount: stageEntries.length,
    drawSize,
    eventId,
  });

  const { seedsCount, isOverride } = resolveSeedsCount({
    requestedValue: inputs[SEEDS_COUNT]?.value,
    groupSize: inputs[GROUP_SIZE]?.value,
    participantsCount: stageEntries.length,
    automaticSeedsCount: thresholdSeedsCount,
    additionalSeedsAllowed,
    thresholdSeedsCount,
    drawSize,
    drawType,
  });

  if (isOverride) {
    // The factory otherwise clamps seedsCount back to the active seeding policy's ceiling. This is
    // an override of that ceiling — how a national rule that seeds more deeply than ITF/USTA gets
    // expressed. Structural limits are untouched: the factory still caps at the stage entry count
    // and at drawSize.
    //
    // A count WITHIN the policy's `additionalSeeds` allowance does not come through here, and must
    // not: the policy is granting those seeds, so disabling policy limits to obtain them would lift
    // the ceiling the allowance exists to define. See `resolveSeedsCount`.
    drawOptions.enforcePolicyLimits = false;
  }

  const qualifiersCount = isQualifyingFirst
    ? (validators.numericValidator(inputs[QUALIFYING_POSITIONS]?.value) &&
        Number.parseInt(inputs[QUALIFYING_POSITIONS]?.value)) ||
      4
    : (validators.numericValidator(inputs[QUALIFIERS_COUNT].value) &&
        Number.parseInt(inputs[QUALIFIERS_COUNT]?.value)) ||
      0;

  if (structureId && drawId) {
    // the round the qualifiers enter; absent (one open round) the factory's link targets round 1
    const roundTarget = Number.parseInt(inputs[QUALIFYING_TARGET_ROUND]?.value, 10) || undefined;
    handleQualifyingStructure({
      structureId,
      qualifiersCount,
      roundTarget,
      structureOptions,
      matchUpFormat,
      structureName,
      automated,
      drawSize,
      drawType,
      drawId,
      eventId,
      callback,
    });
    return;
  }

  const requiredPositions = stageEntries.length + qualifiersCount;
  if (!effectiveIsQualifying && !isPopulateMain && qualifiersCount && drawSize < requiredPositions) {
    tmxToast({
      message: `Draw size (${drawSize}) must be at least ${requiredPositions} (${stageEntries.length} entries + ${qualifiersCount} qualifiers)`,
      intent: IS_WARNING,
      pauseOnHover: true,
    });
    return;
  }

  // Qualifying-first: add qualifyingOnly flag so factory creates MAIN placeholder
  if (isQualifyingFirst) {
    drawOptions.qualifyingOnly = true;
  }

  configureDrawOptions({
    isQualifying: effectiveIsQualifying ?? false,
    existingDrawName,
    qualifiersCount,
    structureOptions,
    matchUpFormat,
    structureName,
    seedsCount,
    drawSize,
    drawType,
    drawName,
    eventId,
    drawOptions,
  });

  // Qualifying-first: wrap callback to auto-position qualifying entries after draw creation
  const effectiveCallback = buildQualifyingFirstCallback(!!isQualifyingFirst, automated, callback);

  if (drawSizeInteger) {
    handleDrawGeneration({ drawOptions, tieFormatName, seedingPolicyDefinition, eventId, callback: effectiveCallback });
  } else {
    tmxToast({
      message: t('drawers.addDraw.invalidDrawSize'),
      intent: IS_WARNING,
      pauseOnHover: true,
    });
  }
}
